import { useEffect, useState } from "react";

function Attendance() {
  const [students, setStudents] = useState([]);
  const [date, setDate] = useState("");

  useEffect(() => {
    setStudents(JSON.parse(localStorage.getItem("students")) || []);
  }, []);

  const markAttendance = (studentId, status) => {
    const attendance = JSON.parse(localStorage.getItem("attendance")) || {};

    if (!attendance[studentId]) attendance[studentId] = {};
    attendance[studentId][date] = status;

    localStorage.setItem("attendance", JSON.stringify(attendance));
    alert("Attendance saved");
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Mark Attendance</h2>

      <input type="date" onChange={e => setDate(e.target.value)} required />
      <br /><br />

      {students.map(s => (
        <div key={s.id} style={{ border: "1px solid #ccc", padding: "10px" }}>
          <b>{s.name}</b>
          <br />
          <button onClick={() => markAttendance(s.id, "Present")}>Present</button>
          <button onClick={() => markAttendance(s.id, "Absent")}>Absent</button>
        </div>
      ))}
    </div>
  );
}

export default Attendance;
